from pathlib import Path
import json,hashlib,datetime
P=Path(__file__).parent
H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
root=Path.cwd()
def doc(rel,url,label,**kw):
 p=root/rel;return {'path':str(p.relative_to(root)),'sha256':H(p),'url':url,'label':label,**kw}
def local(name):return str((P/name).relative_to(root))
current=doc(local('bofip-ptz-current.pdf'),'https://bofip.impots.gouv.fr/export/pdf/314646','BOI-BIC-RICI-10-140-20-10-20210310, export du 19 octobre 2026 ; absence des deux formules vérifiée p.3',source_role='official_commentary_not_missing_norm')
