archive=doc(local('bofip-archive-coupons-1995.html'),'https://bofip-archives.impots.gouv.fr/bofip/27444-AIDA.html/identifiant=4J1-19951101','BOFIP archive 4 J 1 du 1er novembre 1995 : texte des rubriques sans modèles',source_role='official_historical_commentary_no_models')
archive2=doc(local('bofip-documents-coupons.html'),'https://bofip-archives.impots.gouv.fr/bofip/27494-AIDA.html/identifiant=4J1342-19951101','BOFIP archive 4 J 1342 du 1er novembre 1995 : modalités des documents sans modèles',source_role='official_historical_commentary_no_models')
