checks={'as_of':'2026-10-19','canonical_sources_read_entirely':2,'canonical_source_notes_read_entirely':2,'canonical_raw_source_hashes_match':True,'drafts_found_at_snapshot':0,'missing_graphical_items':4,'complete_normative_candidates':0,'documentary_recovery_complete':False,'authenticated_jo_crosscheck_complete':False,'writes_to_db_batches_attachments_publication':False,'candidate_records_parse':len(rows)==2,'artifacts_hashed':len(files)}
